            d1 = (q >> 4) & 0xF
            d2 = (q >> 8) & 0xF
            d3 = (q >> 12) & 0xF
            e1 = 1 if d0 == 9 else 0
            e2 = 1 if (d0 == 9 and d1 == 9) else 0
            e3 = 1 if (d0 == 9 and d1 == 9 and d2 == 9) else 0
            ena = e1 | (e2 << 1) | (e3 << 2)
            d0 += 1
            if d0 == 10:
                d0 = 0
            if e1:
                d1 += 1
                if d1 == 10:
