                    d3 = 0
            q = d0 | (d1 << 4) | (d2 << 8) | (d3 << 12)
        out.append({'q': q, 'ena': ena})
        if 'mid' in row:
            m = row['mid']
            if m.get('reset', 0):
                q = 0
                ena = 0
    return out
